//! Concrete configurations (C1, C2) generated by one macro, so that the two differ only in the listed parameters.
//!
//! C1 : Goldilocks, degree-2 extension, Poseidon2 width 12 (rate 8, capacity 4), Blake3-256 Merkle commitments.
//! C2 : KoalaBear,  degree-4 extension, Poseidon2 width 24 (rate 16, capacity 8), Blake3-256 Merkle commitments,
//!      32/64-bit values in limbs (data.rs `map_c2`).

use p3_challenger::{HashChallenger, SerializingChallenger32, SerializingChallenger64};
use p3_commit::ExtensionMmcs;
use p3_field::extension::BinomialExtensionField;
use p3_fri::{FriParameters, TwoAdicFriPcs};
use p3_blake3::Blake3;
use p3_merkle_tree::MerkleTreeMmcs;
use p3_poseidon2_air::RoundConstants;
use p3_symmetric::{CompressionFunctionFromHasher, Permutation, SerializingHasher};
use p3_uni_stark::{prove, verify, Proof, StarkConfig};

use crate::air::{native_digest, ExecAir, ExecPublic, Layout};
use crate::data::Workload;

/// FRI / proof-of-work options (defaults = the w30 / plan values: blowup 8, 40 queries, 16 PoW bits).
#[derive(Clone, Debug)]
pub struct FriOpts {
    pub log_blowup: usize,
    pub num_queries: usize,
    pub query_pow_bits: usize,
    /// w30: remainder degree 31 (final polynomial length 32 = 2^5)
    pub log_final_poly_len: usize,
    /// w30: folding factor 8 (= 2^3)
    pub max_log_arity: usize,
}

impl Default for FriOpts {
    fn default() -> Self {
        FriOpts { log_blowup: 3, num_queries: 40, query_pow_bits: 16, log_final_poly_len: 5, max_log_arity: 3 }
    }
}

/// w34 (C3): number of queries of the high-security preset `fri=hi`. Chosen with `src/bin/sectable.rs` (estimator only, no
/// timing): the SMALLEST value for which the proven unique-decoding bits of `security.rs` are >= 100 for R_Exec, R_RC and
/// R_Auth at every N in {1e3, 2e3, 5e3, 1e4, 2e4, 5e4, 1e5} (block 100, plain mode, honest trace heights). See README "w34 changes".
pub const HI_NUM_QUERIES: usize = 102;

/// w36 (S2): number of queries of the speed presets `fri=fast2` (log_blowup 2) and `fri=fast1` (log_blowup 1). Chosen with
/// `src/bin/sectable.rs` (estimator only, before any timing; rule fixed in `journal2/UPGRADE-w36-speed-plan.md`): the SMALLEST q for which
/// `security.rs` gives, for R_Exec, R_RC and R_Auth at every N in {1e3, 2e3, 5e3, 1e4, 2e4, 5e4, 1e5} (block 100, plain mode, honest
/// trace heights): conjectured >= 127, unique decoding >= 49 and list decoding >= the `std` value at the same N and relation.
/// Grinding (16), final polynomial length (2^5) and arity (2^3) are those of `std`. `sectable` checks these constants.
pub const FAST2_NUM_QUERIES: usize = 61;
pub const FAST1_NUM_QUERIES: usize = 126;

impl FriOpts {
    /// w36 (S2) `fri=fast2`: log_blowup 2, 16 query PoW bits, final polynomial length and arity as `std`, `FAST2_NUM_QUERIES` queries.
    pub fn fast2() -> Self {
        FriOpts { log_blowup: 2, num_queries: FAST2_NUM_QUERIES, ..Self::default() }
    }
    /// w36 (S2) `fri=fast1`: log_blowup 1, 16 query PoW bits, final polynomial length and arity as `std`, `FAST1_NUM_QUERIES` queries.
    pub fn fast1() -> Self {
        FriOpts { log_blowup: 1, num_queries: FAST1_NUM_QUERIES, ..Self::default() }
    }
    /// Options for the tests: the preset named by the environment variable `PQZ_FRI` (`std` | `hi` | `fast2` | `fast1`), `std` if unset.
    /// Only the test files use this; the library and the binaries take the preset from their own arguments.
    pub fn from_env() -> Self {
        match std::env::var("PQZ_FRI") {
            Ok(v) => Self::preset(&v).unwrap_or_else(|| panic!("PQZ_FRI={v}: unknown preset")),
            Err(_) => Self::std(),
        }
    }
    /// `fri=std`: the stage C / w30-equivalent options (same as `Default`).
    pub fn std() -> Self {
        Self::default()
    }
    /// `fri=hi`: log_blowup 3, 16 query PoW bits, final polynomial length and folding arity as `std`, `HI_NUM_QUERIES` queries.
    pub fn hi() -> Self {
        FriOpts { num_queries: HI_NUM_QUERIES, ..Self::default() }
    }
    /// Parse the command-line value of `fri=` (`std`, `hi`, `fast2` or `fast1`).
    pub fn preset(name: &str) -> Option<Self> {
        match name {
            "std" => Some(Self::std()),
            "hi" => Some(Self::hi()),
            "fast2" => Some(Self::fast2()),
            "fast1" => Some(Self::fast1()),
            _ => None,
        }
    }
}

macro_rules! variant {
    (
        $name:ident, $Val:ty, $deg:literal, $Chal:ident, $Perm:ty, $perm_fn:path,
        $LL:ty, $W:literal, $SBOX:expr, $REG:literal, $HF:expr, $PR:expr, $MODE:literal,
        $rc_init:path, $rc_int:path, $rc_fin:path, $map:path, $label:literal
    ) => {
        pub mod $name {
            use super::*;

            pub type Val = $Val;
            pub type Challenge = BinomialExtensionField<Val, $deg>;
            type ByteHash = Blake3;
            type FieldHash = SerializingHasher<ByteHash>;
            type MyCompress = CompressionFunctionFromHasher<ByteHash, 2, 32>;
            type ValMmcs = MerkleTreeMmcs<Val, u8, FieldHash, MyCompress, 2, 32>;
            type ChallengeMmcs = ExtensionMmcs<Val, Challenge, ValMmcs>;
            type Challenger = $Chal<Val, HashChallenger<u8, ByteHash, 32>>;
            type Dft = p3_dft::Radix2DitParallel<Val>;
            type Pcs = TwoAdicFriPcs<Val, Dft, ValMmcs, ChallengeMmcs>;
            pub type SC = StarkConfig<Pcs, Challenge, Challenger>;
            pub type Air = ExecAir<Val, $LL, $W, { $SBOX }, $REG, { $HF }, { $PR }, $MODE>;
            pub type P = Proof<SC>;
            pub const LABEL: &str = $label;
            pub const MODE: usize = $MODE;
            pub const W: usize = $W;
            pub const SBOX: u64 = $SBOX;
            pub const REG: usize = $REG;
            pub const HF: usize = $HF;
            pub const PR: usize = $PR;

            pub fn config(o: &FriOpts) -> SC {
                let byte_hash = ByteHash {};
                let field_hash = FieldHash::new(byte_hash);
                let compress = MyCompress::new(byte_hash);
                let val_mmcs = ValMmcs::new(field_hash, compress, 0);
                let challenge_mmcs = ChallengeMmcs::new(val_mmcs.clone());
                let fri = FriParameters {
                    log_blowup: o.log_blowup,
                    log_final_poly_len: o.log_final_poly_len,
                    max_log_arity: o.max_log_arity,
                    num_queries: o.num_queries,
                    batch_proof_of_work_bits: 0,
                    commit_proof_of_work_bits: 0,
                    query_proof_of_work_bits: o.query_pow_bits,
                    mmcs: challenge_mmcs,
                };
                let pcs = Pcs::new(Dft::default(), val_mmcs, fri);
                let challenger = Challenger::from_hasher(vec![], byte_hash);
                SC::new(pcs, challenger)
            }

            /// Canonical Poseidon2 constants (same as the reference permutation `perm()`).
            pub fn consts() -> RoundConstants<Val, $W, { $HF }, { $PR }> {
                RoundConstants::new($rc_init, $rc_int, $rc_fin)
            }
            pub fn perm() -> $Perm {
                $perm_fn()
            }
            pub fn air(theta: u64, n_words: u64) -> Air {
                Air::new(consts(), theta, n_words)
            }
            pub fn lay() -> Layout {
                air(1 << 31, 2).lay
            }
            /// Words of the workload mapped to this config's absorbed encoding.
            pub fn words(w: &Workload) -> Vec<Vec<u64>> {
                w.words.iter().map(|x| $map(x)).collect()
            }
            /// Honest public inputs: digest from the native (non-circuit) sponge, count/sum from the integer
            /// reference function `Workload::reference_result*` (no circuit code involved).
            pub fn public_for(w: &Workload, theta: u64, ctx: [u64; 4]) -> ExecPublic {
                let lay = lay();
                let digest = native_digest::<Val, $W, _>(&lay, &perm(), &words(w));
                let (count, sum) = if $MODE == 0 {
                    let (c, s) = w.reference_result(theta);
                    (c, vec![s])
                } else {
                    let (c, lo, hi) = w.reference_result_limbs(theta);
                    (c, vec![lo, hi])
                };
                ExecPublic { digest, n_blocks: w.n_blocks, block_size: w.block_size, theta, count, sum, ctx }
            }
            /// Prover: witness from `w` (may differ from the data behind `p`, for the rejection tests).
            pub fn prove_with(o: &FriOpts, w: &Workload, p: &ExecPublic) -> Result<P, String> {
                let a = air(p.theta, p.n_words() as u64);
                let trace = a.build_trace(&perm(), &words(w));
                let pv = p.to_values::<Val>(&a.lay);
                prove(&config(o), &a, trace, &pv).map_err(|e| format!("{e:?}"))
            }
            pub fn verify_with(o: &FriOpts, proof: &P, p: &ExecPublic) -> Result<(), String> {
                let a = air(p.theta, p.n_words() as u64);
                let pv = p.to_values::<Val>(&a.lay);
                verify(&config(o), &a, proof, &pv).map_err(|e| format!("{e:?}"))
            }
            pub fn to_bytes(proof: &P) -> Vec<u8> {
                bincode::serialize(proof).expect("serialize")
            }
            pub fn from_bytes(b: &[u8]) -> Result<P, String> {
                bincode::deserialize(b).map_err(|e| format!("{e}"))
            }
            /// Number of trace rows for `n_words` words.
            pub fn n_rows(n_words: usize) -> usize {
                n_words.next_power_of_two().max(crate::air::MIN_ROWS)
            }
            /// Inputs of the security estimator (`security.rs`) for these options and a trace of `trace_len` rows.
            pub fn sec_input(o: &FriOpts, trace_len: usize) -> crate::security::SecInput {
                crate::security::SecInput {
                    base_field_bits: 64 - <Val as p3_field::PrimeField64>::ORDER_U64.leading_zeros(),
                    ext_degree: $deg,
                    trace_len,
                    blowup: 1 << o.log_blowup,
                    num_queries: o.num_queries,
                    grinding: o.query_pow_bits as u32,
                    folding_factor: 1 << o.max_log_arity,
                    num_fri_layers: crate::security::plonky3_layers(
                        trace_len.trailing_zeros() as usize,
                        o.log_blowup,
                        o.log_final_poly_len,
                        o.max_log_arity,
                    ),
                    collision_resistance: 128, // Blake3-256
                }
            }
            /// Reference permutation applied by the AIR trace: used by the tests.
            pub fn perm_ref(x: [Val; $W]) -> [Val; $W] {
                perm().permute(x)
            }
        }
    };
}

variant!(
    c1, p3_goldilocks::Goldilocks, 2, SerializingChallenger64,
    p3_goldilocks::Poseidon2Goldilocks<12>, p3_goldilocks::default_goldilocks_poseidon2_12,
    p3_goldilocks::GenericPoseidon2LinearLayersGoldilocks, 12,
    7u64, 1,
    p3_goldilocks::GOLDILOCKS_POSEIDON2_HALF_FULL_ROUNDS, p3_goldilocks::GOLDILOCKS_POSEIDON2_PARTIAL_ROUNDS_12, 0,
    p3_goldilocks::GOLDILOCKS_POSEIDON2_RC_12_EXTERNAL_INITIAL,
    p3_goldilocks::GOLDILOCKS_POSEIDON2_RC_12_INTERNAL,
    p3_goldilocks::GOLDILOCKS_POSEIDON2_RC_12_EXTERNAL_FINAL,
    crate::data::map_c1,
    "C1 Goldilocks/ext2/Poseidon2-12 (sbox 7, 1 register, degree 3)/Blake3"
);

variant!(
    c1r0, p3_goldilocks::Goldilocks, 2, SerializingChallenger64,
    p3_goldilocks::Poseidon2Goldilocks<12>, p3_goldilocks::default_goldilocks_poseidon2_12,
    p3_goldilocks::GenericPoseidon2LinearLayersGoldilocks, 12,
    7u64, 0,
    p3_goldilocks::GOLDILOCKS_POSEIDON2_HALF_FULL_ROUNDS, p3_goldilocks::GOLDILOCKS_POSEIDON2_PARTIAL_ROUNDS_12, 0,
    p3_goldilocks::GOLDILOCKS_POSEIDON2_RC_12_EXTERNAL_INITIAL,
    p3_goldilocks::GOLDILOCKS_POSEIDON2_RC_12_INTERNAL,
    p3_goldilocks::GOLDILOCKS_POSEIDON2_RC_12_EXTERNAL_FINAL,
    crate::data::map_c1,
    "C1 Goldilocks/ext2/Poseidon2-12 (sbox 7, 0 registers, degree 7)/Blake3"
);

variant!(
    c2, p3_koala_bear::KoalaBear, 4, SerializingChallenger32,
    p3_koala_bear::Poseidon2KoalaBear<24>, p3_koala_bear::default_koalabear_poseidon2_24,
    p3_koala_bear::GenericPoseidon2LinearLayersKoalaBear, 24,
    p3_koala_bear::KOALABEAR_S_BOX_DEGREE, 0,
    p3_koala_bear::KOALABEAR_POSEIDON2_HALF_FULL_ROUNDS, p3_koala_bear::KOALABEAR_POSEIDON2_PARTIAL_ROUNDS_24, 1,
    p3_koala_bear::KOALABEAR_POSEIDON2_RC_24_EXTERNAL_INITIAL,
    p3_koala_bear::KOALABEAR_POSEIDON2_RC_24_INTERNAL,
    p3_koala_bear::KOALABEAR_POSEIDON2_RC_24_EXTERNAL_FINAL,
    crate::data::map_c2,
    "C2 KoalaBear/ext4/Poseidon2-24 (sbox 3, degree 3)/Blake3, limbs"
);

/// C1 in HIDING (zero-knowledge) mode: `HidingFriPcs` + `MerkleTreeHidingMmcs` (as in p3-poseidon2-air's
/// `prove_poseidon2_baby_bear_keccak_zk.rs`), same AIR, field, Blake3 hash and FRI options as `c1`.
/// Salts: 4 field elements per leaf (as the example); random codewords: 4 (the example's value; at least the
/// extension degree 2 is required). The RNGs are seeded with fixed seeds so that benchmark runs are repeatable;
/// a real deployment must seed them from the operating system (see the doc comments in p3-fri hiding_pcs.rs).
pub mod c1zk {
    use super::*;
    use p3_fri::HidingFriPcs;
    use p3_merkle_tree::MerkleTreeHidingMmcs;
    use rand::rngs::StdRng;
    use rand::SeedableRng;

    pub use super::c1::{air, consts, lay, n_rows, perm, perm_ref, public_for, words, Air, Challenge, Val, HF, MODE, PR, REG, SBOX, W};

    type ByteHash = Blake3;
    type FieldHash = SerializingHasher<ByteHash>;
    type MyCompress = CompressionFunctionFromHasher<ByteHash, 2, 32>;
    type ValMmcs = MerkleTreeHidingMmcs<Val, u8, FieldHash, MyCompress, StdRng, 2, 32, 4>;
    type ChallengeMmcs = ExtensionMmcs<Val, Challenge, ValMmcs>;
    type Challenger = SerializingChallenger64<Val, HashChallenger<u8, ByteHash, 32>>;
    type Dft = p3_dft::Radix2DitParallel<Val>;
    type Pcs = HidingFriPcs<Val, Dft, ValMmcs, ChallengeMmcs, StdRng>;
    pub type SC = StarkConfig<Pcs, Challenge, Challenger>;
    pub type P = Proof<SC>;
    pub const LABEL: &str = "C1ZK Goldilocks/ext2/Poseidon2-12 (sbox 7, 1 register, degree 3)/Blake3, hiding PCS";
    pub const NUM_RANDOM_CODEWORDS: usize = 4;

    pub fn config(o: &FriOpts) -> SC {
        let byte_hash = ByteHash {};
        let field_hash = FieldHash::new(byte_hash);
        let compress = MyCompress::new(byte_hash);
        let val_mmcs = ValMmcs::new(field_hash, compress, 0, StdRng::seed_from_u64(1));
        let challenge_mmcs = ChallengeMmcs::new(val_mmcs.clone());
        let fri = FriParameters {
            log_blowup: o.log_blowup,
            log_final_poly_len: o.log_final_poly_len,
            max_log_arity: o.max_log_arity,
            num_queries: o.num_queries,
            batch_proof_of_work_bits: 0,
            commit_proof_of_work_bits: 0,
            query_proof_of_work_bits: o.query_pow_bits,
            mmcs: challenge_mmcs,
        };
        let pcs = Pcs::new(Dft::default(), val_mmcs, fri, NUM_RANDOM_CODEWORDS, StdRng::seed_from_u64(2));
        let challenger = Challenger::from_hasher(vec![], byte_hash);
        SC::new(pcs, challenger)
    }
    pub fn prove_with(o: &FriOpts, w: &Workload, p: &ExecPublic) -> Result<P, String> {
        let a = air(p.theta, p.n_words() as u64);
        let trace = a.build_trace(&perm(), &words(w));
        let pv = p.to_values::<Val>(&a.lay);
        prove(&config(o), &a, trace, &pv).map_err(|e| format!("{e:?}"))
    }
    pub fn verify_with(o: &FriOpts, proof: &P, p: &ExecPublic) -> Result<(), String> {
        let a = air(p.theta, p.n_words() as u64);
        let pv = p.to_values::<Val>(&a.lay);
        verify(&config(o), &a, proof, &pv).map_err(|e| format!("{e:?}"))
    }
    pub fn to_bytes(proof: &P) -> Vec<u8> {
        bincode::serialize(proof).expect("serialize")
    }
    pub fn from_bytes(b: &[u8]) -> Result<P, String> {
        bincode::deserialize(b).map_err(|e| format!("{e}"))
    }
    /// Security-estimator inputs. The ZK trace domain is twice as long (p3-uni-stark prover.rs: `trace domain doubles when ZK`);
    /// `trace_len` here is the length used for the estimate: the honest-AIR rows times 2.
    pub fn sec_input(o: &FriOpts, trace_len: usize) -> crate::security::SecInput {
        super::c1::sec_input(o, trace_len * 2)
    }
}
